package com.smeal.controller; import com.smeal.dto.NutritionDataDTO;import com.smeal.service.NutritionService;import java.util.List;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/nutrition/foods") public class NutritionController {private final NutritionService s;public NutritionController(NutritionService s){this.s=s;}@GetMapping public List<NutritionDataDTO> search(@RequestParam(required=false)String search,@RequestParam(defaultValue="50")int limit){return s.search(search,limit);}@GetMapping("/{name}")public NutritionDataDTO get(@PathVariable String name){return s.get(name);}}
